<?php declare(strict_types=1);require_once __DIR__.'/includes/functions.php';$lang=lang();$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM news WHERE id=? AND is_published=1');$s->execute([$id]);$n=$s->fetch();if(!$n){http_response_code(404);$pageTitle='Story not found';require __DIR__.'/includes/header.php';?><section class="section"><div class="container empty-state"><span class="empty-icon">✳</span><h1>Story not found</h1><p>This story may have been removed or is not currently published.</p><a class="btn primary" href="news.php">Browse news</a></div></section><?php require __DIR__.'/includes/footer.php';exit;}if(post()){verifyCsrf();if(isset($_POST['like']))toggleLike('news',$id);if(isset($_POST['comment'])){$u=requireVerifiedUser();$body=clean('body',2000);if($body)db()->prepare("INSERT INTO comments(user_id,content_type,content_id,body) VALUES(?,?,?,?)")->execute([$u['id'],'news',$id,$body]);}redirect('article.php?id='.$id);} $comments=commentsFor('news',$id);$pageTitle=localTitle($n,$lang);require __DIR__.'/includes/header.php';?><section class="section"><div class="container" style="max-width:900px"><p class="eyebrow"><?=e($n['category'])?> · <?=e($n['published_at'])?></p><h1 class="section-title"><?=e(localTitle($n,$lang))?></h1><?php if($n['featured_image']):?><img class="detail-image" src="<?=e($n['featured_image'])?>" alt="<?=e(localTitle($n,$lang))?>"><?php endif;?><div class="copy" style="max-width:none;margin-top:25px"><?=nl2br(e(localBody($n,$lang)))?></div><div class="like-row"><form method="post"><?=csrfField()?><button class="like-btn" name="like">♡ Like · <?=likeCount('news',$id)?></button></form></div><div class="form-shell" style="margin:35px 0"><h2>Comments</h2><?php if(currentUser()&&((int)currentUser()['email_verified']||currentUser()['role']==='admin')):?><form method="post"><?=csrfField()?><textarea name="body" placeholder="Write a comment..."></textarea><button class="btn primary" name="comment" style="margin-top:10px">Comment</button></form><?php else:?><p>Verified users can comment.</p><?php endif;?><?php foreach($comments as $c):?><div class="comment"><b><?=e($c['full_name'])?></b><div class="comment-meta"><?=e($c['created_at'])?></div><p><?=nl2br(e($c['body']))?></p></div><?php endforeach;?></div></div></section><?php require __DIR__.'/includes/footer.php';
